def walk(p):
    out = []
    for name in repo.list(p):
        full = p + "/" + name if p != "." else name
        if name.endswith("/"):
            out.extend(walk(full.rstrip("/")))
        else:
            out.append(full)
    return out

all_files = walk("src")
info = []
for f in all_files:
    c = repo.read(f)
    info.append({"path": f, "bytes": len(c), "legacy": c.count("legacy_flag"), "legacy_upper": c.count("LEGACY_FLAG")})
result({"files": info})

